// Single registrar for the offline service worker (generated by vite-plugin-pwa).
// "ready" only after the engine, game code, page AND videos are in Cache Storage.
// "partial" = chess works offline but some videos are still missing (retry offered).
export type OfflineStatus = "unsupported" | "preparing" | "ready" | "partial" | "error";
type Listener = (s: OfflineStatus, detail?: string) => void;

const PROJECT_ID = "2b16136d-f4bf-4710-99be-72c008a6e328";
export const VIDEOS = [
  "/videos/intro-arca-horizontal.mp4",
  "/videos/intro-arca-vertical.mp4",
  "/videos/nyx-reclutada-horizontal.mp4",
  "/videos/nyx-reclutada-vertical.mp4",
];
let status: OfflineStatus = "unsupported";
let detail = "";
const listeners = new Set<Listener>();
const setStatus = (s: OfflineStatus, d = "") => {
  status = s;
  detail = d;
  listeners.forEach((l) => l(s, d));
};
export const subscribe = (l: Listener) => (listeners.add(l), l(status, detail), () => listeners.delete(l));

function refused(): boolean {
  if (!import.meta.env.PROD) return true;
  if (window.self !== window.top) return true;
  const h = window.location.hostname.toLowerCase();
  const first = h.split(".")[0] ?? "";
  if (/\.(lovable\.app|gpt-eng\.com|gptengineer\.run)$/.test(h)) {
    if (/^(?:id-preview|preview)(?:-[a-z0-9]+)?--.+$/.test(first)) return true;
    if (first === `project--${PROJECT_ID}-dev`) return true;
  }
  if (/(^|\.)lovableproject(-dev)?\.com$/.test(h)) return true;
  if (/(^|\.)beta\.lovable\.dev$/.test(h)) return true;
  if (new URLSearchParams(window.location.search).get("sw") === "off") return true;
  return false;
}

async function unregisterOwn() {
  const regs = await navigator.serviceWorker.getRegistrations();
  await Promise.all(
    regs.filter((r) => r.active?.scriptURL.endsWith("/sw.js") || r.installing?.scriptURL.endsWith("/sw.js")).map((r) => r.unregister()),
  );
}

const withTimeout = <T,>(p: Promise<T>, ms: number) =>
  Promise.race([p, new Promise<never>((_, rej) => setTimeout(() => rej(new Error("tiempo agotado")), ms))]);

async function cachedPaths() {
  const urls = new Set<string>();
  for (const k of await caches.keys()) for (const r of await (await caches.open(k)).keys()) urls.add(new URL(r.url).pathname);
  return urls;
}

// A cached video is valid only if it is a non-empty 200 video/mp4 (never an HTML error page).
async function videoOk(path: string) {
  const r = await caches.match(path, { ignoreSearch: true });
  if (!r || r.status !== 200 || !(r.headers.get("content-type") || "").includes("video/mp4")) return false;
  return (await r.clone().arrayBuffer()).byteLength > 1000;
}

async function verify(): Promise<string[]> {
  const page = await withTimeout(fetch("/", { cache: "no-store" }), 15000);
  if (!page.ok) throw new Error("no se pudo guardar la pantalla del juego");
  const urls = await cachedPaths();
  const need: [string, (p: string) => boolean][] = [
    ["motor", (p) => p === "/wasm/fairy-stockfish.wasm"],
    ["worker", (p) => /\/assets\/worker-.*\.js$/.test(p)],
    ["juego", (p) => /\/assets\/Game-.*\.js$/.test(p)],
    ["pantalla", (p) => p === "/"],
  ];
  const missing = need.filter(([, t]) => ![...urls].some(t)).map(([n]) => n);
  if (missing.length) throw new Error("faltan: " + missing.join(", "));
  // Videos: fetch whole files (no Range) through the SW so it stores complete responses.
  const pending: string[] = [];
  for (const v of VIDEOS) {
    if (await videoOk(v)) continue;
    try {
      const r = await withTimeout(fetch(v), 30000);
      await r.arrayBuffer();
    } catch {
      /* checked below */
    }
    if (!(await videoOk(v))) pending.push(v.split("/").pop() || v);
  }
  return pending;
}

// Each attempt has a generation; a stale (hung) attempt can never overwrite a newer status.
let gen = 0;
export function prepareOffline(): Promise<void> {
  if (typeof window === "undefined" || !("serviceWorker" in navigator)) return Promise.resolve();
  return run(++gen);
}

async function run(g: number) {
  const set = (s: OfflineStatus, d = "") => g === gen && setStatus(s, d);
  if (refused()) {
    await unregisterOwn().catch(() => {});
    return;
  }
  if (!navigator.onLine) return void set("error", "sin conexión");
  set("preparing");
  try {
    await navigator.serviceWorker.register("/sw.js", { scope: "/" });
    await withTimeout(navigator.serviceWorker.ready, 20000);
    if (!navigator.serviceWorker.controller) {
      await withTimeout(
        new Promise<void>((res) => navigator.serviceWorker.addEventListener("controllerchange", () => res(), { once: true })),
        20000,
      );
    }
    const pending = await verify();
    if (pending.length) set("partial", "vídeos pendientes: " + pending.join(", "));
    else set("ready");
  } catch (e) {
    set("error", navigator.onLine ? (e as Error).message : "sin conexión");
  }
}

// When the connection drops mid-preparation, fail fast so "Reintentar" appears;
// when it returns, retry automatically.
if (typeof window !== "undefined") {
  window.addEventListener("offline", () => status === "preparing" && (gen++, setStatus("error", "sin conexión")));
  window.addEventListener("online", () => (status === "error" || status === "partial") && prepareOffline());
}
